/** Every upload is re-encoded to this format before it is stored. */
export const STORED_IMAGE_TYPE = 'image/webp';

/** Storage keys are generated by the server only, never derived from user input. */
export function projectImageStorageKey(projectId: string, imageId: string): string {
  return `projects/${projectId}/${imageId}.webp`;
}

/** New images are appended after the last one. */
export function nextSortOrder(currentMax: number | null): number {
  return (currentMax ?? -1) + 1;
}
